+                        .withBody("{\"items\":[" +
+                                "{\"id\":5,\"date\":\"2018-11-15\",\"description\":\"test visit for pet 1\",\"petId\":1}," +
+                                "{\"id\":6,\"date\":\"2018-11-16\",\"description\":\"test visit for pet 2\",\"petId\":2}" +
+                                "]}")));
