diff --git a/spring-petclinic-api-gateway/src/test/java/org/springframework/samples/petclinic/api/application/CustomersServiceClientIntegrationTest.java b/spring-petclinic-api-gateway/src/test/java/org/springframework/samples/petclinic/api/application/CustomersServiceClientIntegrationTest.java
