diff --git a/src/main/java/org/springframework/samples/petclinic/security/DataInitializer.java b/src/main/java/org/springframework/samples/petclinic/security/DataInitializer.java
new file mode 100644
index 000000000..10f4f7df7
--- /dev/null
+++ b/src/main/java/org/springframework/samples/petclinic/security/DataInitializer.java
@@ -0,0 +1,114 @@
+package org.springframework.samples.petclinic.security;
+
+import org.springframework.boot.CommandLineRunner;
+import org.springframework.security.crypto.password.PasswordEncoder;
+import org.springframework.stereotype.Component;
+
+import javax.sql.DataSource;
+import java.sql.Connection;
+import java.sql.PreparedStatement;
+import java.sql.ResultSet;
+import java.sql.SQLException;
+
+/**
+ * Initializes predefined tenants and users on application startup.
+ */
+@Component
+public class DataInitializer implements CommandLineRunner {
+
+    private final DataSource dataSource;
+
+    private final PasswordEncoder passwordEncoder;
+
+    public DataInitializer(DataSource dataSource, PasswordEncoder passwordEncoder) {
+        this.dataSource = dataSource;
+        this.passwordEncoder = passwordEncoder;
+    }
+
+    @Override
+    public void run(String... args) throws Exception {
+        // Create predefined tenants and users
+        createTenantUser("tenant-1", "user-1", "password", true);
+        createTenantUser("tenant-2", "user-2", "password", true);
+    }
+
+    private void createTenantUser(String tenantId, String username, String password, boolean enabled) {
+        // Check if user already exists
+        if (userExists(username)) {
+            updateUserTenant(username, tenantId);
+            return;
+        }
+
+        // Create user with tenant
+        String sql = "INSERT INTO users (username, password, enabled, tenant_id) VALUES (?, ?, ?, ?)";
+
+        try (Connection conn = dataSource.getConnection();
+             PreparedStatement ps = conn.prepareStatement(sql)) {
+
+            ps.setString(1, username);
+            ps.setString(2, passwordEncoder.encode(password));
+            ps.setBoolean(3, enabled);
+            ps.setString(4, tenantId);
+
+            ps.executeUpdate();
+
+            // Add ADMIN role to the user
+            addRole(username, "ROLE_ADMIN");
+
+        } catch (SQLException e) {
+            throw new RuntimeException("Error creating tenant user", e);
+        }
+    }
+
+    private boolean userExists(String username) {
+        String sql = "SELECT COUNT(*) FROM users WHERE username = ?";
+
+        try (Connection conn = dataSource.getConnection();
+             PreparedStatement ps = conn.prepareStatement(sql)) {
+
+            ps.setString(1, username);
+
+            try (ResultSet rs = ps.executeQuery()) {
+                if (rs.next()) {
+                    return rs.getInt(1) > 0;
+                }
+            }
+        } catch (SQLException e) {
+            throw new RuntimeException("Error checking if user exists", e);
+        }
+
+        return false;
+    }
+
+    private void updateUserTenant(String username, String tenantId) {
+        String sql = "UPDATE users SET tenant_id = ? WHERE username = ?";
+
+        try (Connection conn = dataSource.getConnection();
+             PreparedStatement ps = conn.prepareStatement(sql)) {
+
+            ps.setString(1, tenantId);
+            ps.setString(2, username);
+
+            ps.executeUpdate();
+
+        } catch (SQLException e) {
+            throw new RuntimeException("Error updating user tenant", e);
+        }
+    }
+
+    private void addRole(String username, String role) {
+        String sql = "INSERT INTO roles (username, role) VALUES (?, ?)";
+
+        try (Connection conn = dataSource.getConnection();
+             PreparedStatement ps = conn.prepareStatement(sql)) {
+
+            ps.setString(1, username);
+            ps.setString(2, role);
+
+            ps.executeUpdate();
+
+        } catch (SQLException e) {
+            throw new RuntimeException("Error adding role to user", e);
+        }
+    }
+}

diff --git a/src/main/java/org/springframework/samples/petclinic/security/TenantAwareAuthenticationProvider.java b/src/main/java/org/springframework/samples/petclinic/security/TenantAwareAuthenticationProvider.java
new file mode 100644
index 000000000..44a484793
--- /dev/null
+++ b/src/main/java/org/springframework/samples/petclinic/security/TenantAwareAuthenticationProvider.java
@@ -0,0 +1,68 @@
+package org.springframework.samples.petclinic.security;
+
+import org.springframework.security.authentication.BadCredentialsException;
+import org.springframework.security.authentication.dao.DaoAuthenticationProvider;
+import org.springframework.security.core.Authentication;
+import org.springframework.security.core.AuthenticationException;
+import org.springframework.security.core.userdetails.UserDetailsService;
+
+import javax.sql.DataSource;
+import java.sql.Connection;
+import java.sql.PreparedStatement;
+import java.sql.ResultSet;
+import java.sql.SQLException;
+
+/**
+ * Custom authentication provider that validates tenant access.
+ * Extends the DaoAuthenticationProvider to add tenant validation.
+ */
+public class TenantAwareAuthenticationProvider extends DaoAuthenticationProvider {
+
+    private final DataSource dataSource;
+
+    public TenantAwareAuthenticationProvider(UserDetailsService userDetailsService, DataSource dataSource) {
+        super(userDetailsService);
+        this.dataSource = dataSource;
+    }
+
+    @Override
+    public Authentication authenticate(Authentication authentication) throws AuthenticationException {
+        // First, authenticate using the parent provider
+        Authentication result = super.authenticate(authentication);
+
+        // Then, validate tenant access
+        String username = authentication.getName();
+        String currentTenant = TenantContext.getCurrentTenant();
+
+        if (currentTenant == null || currentTenant.isEmpty()) {
+            throw new BadCredentialsException("Tenant is not set");
+        }
+
+        if (!validateTenantAccess(username, currentTenant)) {
+            throw new BadCredentialsException("User does not have access to tenant: " + currentTenant);
+        }
+
+        return result;
+    }
+
+    private boolean validateTenantAccess(String username, String tenantId) {
+        String sql = "SELECT COUNT(*) FROM users WHERE username = ? AND tenant_id = ?";
+
+        try (Connection conn = dataSource.getConnection();
+             PreparedStatement ps = conn.prepareStatement(sql)) {
+
+            ps.setString(1, username);
+            ps.setString(2, tenantId);
+
+            try (ResultSet rs = ps.executeQuery()) {
+                if (rs.next()) {
+                    return rs.getInt(1) > 0;
+                }
+            }
+        } catch (SQLException e) {
+            throw new RuntimeException("Error validating tenant access", e);
+        }
+
+        return false;
+    }
+}

