@@ -0,0 +1,38 @@
+package org.springframework.samples.petclinic.security;
+
+/**
+ * Utility class to store and retrieve the current tenant ID.
+ * Uses ThreadLocal to ensure thread safety.
+ */
+public class TenantContext {
+    private static final ThreadLocal<String> CURRENT_TENANT = new ThreadLocal<>();
+
+    private TenantContext() {
+        // Private constructor to prevent instantiation
+    }
+
+    /**
+     * Set the current tenant ID.
+     *
+     * @param tenantId the tenant ID to set
+     */
+    public static void setCurrentTenant(String tenantId) {
+        CURRENT_TENANT.set(tenantId);
+    }
+
+    /**
+     * Get the current tenant ID.
+     *
+     * @return the current tenant ID
+     */
+    public static String getCurrentTenant() {
+        return CURRENT_TENANT.get();
+    }
+
+    /**
+     * Clear the current tenant ID.
+     */
+    public static void clear() {
+        CURRENT_TENANT.remove();
+    }
+}

diff --git a/src/main/java/org/springframework/samples/petclinic/security/TenantFilter.java b/src/main/java/org/springframework/samples/petclinic/security/TenantFilter.java
new file mode 100644
index 000000000..673354c8f
--- /dev/null
+++ b/src/main/java/org/springframework/samples/petclinic/security/TenantFilter.java
@@ -0,0 +1,38 @@
+package org.springframework.samples.petclinic.security;
+
+import jakarta.servlet.FilterChain;
+import jakarta.servlet.ServletException;
+import jakarta.servlet.http.HttpServletRequest;
+import jakarta.servlet.http.HttpServletResponse;
+import org.springframework.core.Ordered;
+import org.springframework.core.annotation.Order;
+import org.springframework.stereotype.Component;
+import org.springframework.web.filter.OncePerRequestFilter;
+
+import java.io.IOException;
+
+/**
+ * Filter to extract tenant information from the X-TENANT-ID header
+ * and set it in the TenantContext.
+ */
+@Component
+@Order(Ordered.HIGHEST_PRECEDENCE)
+public class TenantFilter extends OncePerRequestFilter {
+
+    private static final String TENANT_HEADER = "X-TENANT-ID";
+
+    @Override
+    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain filterChain)
+            throws ServletException, IOException {
+        try {
+            String tenantId = request.getHeader(TENANT_HEADER);
+            if (tenantId != null && !tenantId.isEmpty()) {
+                TenantContext.setCurrentTenant(tenantId);
+            }
+            filterChain.doFilter(request, response);
+        } finally {
+            // Clear the tenant context after the request is processed
+            TenantContext.clear();
+        }
+    }
+}

